#define EI_NIDENT 16
typedef uint64_t Elf64_Addr;
typedef uint64_t Elf64_Off;
typedef uint16_t Elf64_Half;
typedef uint32_t Elf64_Word;

struct Elf64_Ehdr {
    unsigned char e_ident[EI_NIDENT]; /* Magic, Class (32/64), Data (Endian) */
    Elf64_Half    e_type;           /* ET_REL (1), ET_EXEC (2), ET_DYN (3) */
    Elf64_Half    e_machine;        /* Architecture (EM_X86_64) */
    Elf64_Word    e_version;
    Elf64_Addr    e_entry;          /* Entry point Virtual Memory Address */
    Elf64_Off     e_phoff;          /* Program Header Table offset (for loader) */
    Elf64_Off     e_shoff;          /* Section Header Table offset (for linker) */
    Elf64_Half    e_ehsize;         /* Size of this header (64 bytes) */
    Elf64_Half    e_phnum;          /* Num entries in PHT */
    Elf64_Half    e_shnum;          /* Num entries in SHT */
    Elf64_Half    e_shstrndx;       /* Index of section names string table */
};
